{"path": "tests/test_command_decorators.py", "content": "import click


def test_command_custom_cls(runner):
    """Using ``cls`` with ``@click.command`` should return an instance
    of the given class.
    """

    class CustomCommand(click.Command):
        pass

    @click.command(cls=CustomCommand)
    def cli():
        click.echo("hello")

    assert isinstance(cli, CustomCommand)
    result = runner.invoke(cli)
    assert result.exception is None
    assert result.output == "hello\n""}
